import pandas as pd
import numpy as np

# Load the NO2 data
no2_data = pd.read_csv('chunks_csv/changespillover/changespillover_2021_2022_no2.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values by imputing with the mean of the respective year
no2_data['NO2_2021'].fillna(no2_data['NO2_2021'].mean(), inplace=True)
no2_data['NO2_2022'].fillna(no2_data['NO2_2022'].mean(), inplace=True)

# Re-check for any remaining missing values and drop those rows
no2_data.dropna(inplace=True)

# Calculate change in NO2
no2_data['change'] = no2_data['NO2_2022'] - no2_data['NO2_2021']

# Categorize changes
def categorize_change(change):
    if change > 0:
        return 'Increase'
    elif change < 0:
        return 'Decrease'
    else:
        return 'No Change'

no2_data['change_category'] = no2_data['change'].apply(categorize_change)

# Create a mapping of boroughs to their change categories
change_map = no2_data.set_index('borough')['change_category'].to_dict()

# Create a contingency table for neighboring boroughs
contingency_table = {'Increase': 0, 'Decrease': 0, 'No Change': 0}

for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']

    if borough in change_map and neighbor in change_map:
        if change_map[borough] == change_map[neighbor]:
            if change_map[borough] == 'Increase':
                contingency_table['Increase'] += 1
            elif change_map[borough] == 'Decrease':
                contingency_table['Decrease'] += 1

# Total number of data points used
data_points_used = len(no2_data)

# Calculate the observed statistic
observed_statistic = (contingency_table['Increase'] + contingency_table['Decrease']) / data_points_used

# Permutation test
num_permutations = 500
permuted_statistics = []

for _ in range(num_permutations):
    shuffled_categories = np.random.permutation(no2_data['change_category'].values)
    shuffled_table = {'Increase': 0, 'Decrease': 0}

    for i, (borough, neighbor) in enumerate(zip(no2_data['borough'], adjacency_data['neighbor'])):
        if borough in change_map and neighbor in change_map:
            if shuffled_categories[i] == shuffled_categories[adjacency_data['borough'].tolist().index(neighbor)]:
                if shuffled_categories[i] == 'Increase':
                    shuffled_table['Increase'] += 1
                elif shuffled_categories[i] == 'Decrease':
                    shuffled_table['Decrease'] += 1

    permuted_statistic = (shuffled_table['Increase'] + shuffled_table['Decrease']) / data_points_used
    permuted_statistics.append(permuted_statistic)

# Calculate p-value
p_value = np.sum(np.array(permuted_statistics) >= observed_statistic) / num_permutations

# Print results
print(f"data_points_used = {data_points_used}")
if p_value < 0.05:
    conclusion = "CLUSTERED"
else:
    conclusion = "NOT CLUSTERED"

print(f"FINAL ANSWER: {conclusion} (test statistic = {observed_statistic}, p = {p_value})")
